namespace FormatFactoryWinUI.Services;

internal static class MediaOutputLocalizationResources
{
    internal static readonly LocalizedResourceModule Module = new("MediaOutput",
        MediaOutputResourceData.Entries.Select(entry => new LocalizedResourceEntry(entry.Key,
            LocalizedResourceModule.LegacyLanguageCodes.Select(code => MediaOutputResourceData.Translate(code, entry.Key)).ToArray())).ToArray());
}

